.hint-title { font-size:.7rem; font-weight:600; color:#22c55e; margin-bottom:.3rem; }
.ref-hint ol { margin:0; padding-right:1.2rem; font-size:.65rem; color:#8B95A5; }
.ref-hint li { margin-bottom:.15rem; }

